import {linkedTypeLabels} from '../features/chapters/linked-prose-highlights.mjs';
import {storyTimeLabel} from './story-time-label.mjs';
import {useModules} from '../modules/context.tsx';
import React from 'react';
import {chapterShadows} from './useStoryLinks.js';
import {Icon} from './icons.tsx';
export function ChapterRibbon({call,novelId,tick,chapterId,onMemory,onStoryCard,onForeshadow,resource,highlightControl}){
 const modules=useModules(),data=resource?.value;
 if(!data)return resource.error?<p className="notice">联动资料读取失败，正文草稿仍保留。</p>:null;
 const people=data.nodes.filter(n=>data.links.some(l=>l.nodeId===n.id&&l.chapterId===chapterId&&!l.deleted&&!l.excluded));
 const cards=data.cards.filter(c=>c.chapterIds.includes(chapterId)),shadows=modules.foreshadow?chapterShadows(data,chapterId):[];
 if(!people.length&&!cards.length&&!shadows.length&&!highlightControl?.total)return null;
 return <aside className="chapter-ribbon" aria-label="本章故事联动"><header className="chapter-ribbon-heading"><h3>本章关联卡片</h3>{highlightControl&&<button type="button" aria-pressed={highlightControl.enabled} onPointerDown={highlightControl.onPointerDown} onClick={highlightControl.onToggle}>{highlightControl.enabled?'隐藏关联高亮':'显示关联高亮'}</button>}</header>{highlightControl?.enabled&&<p className="chapter-highlight-status" role="status">{highlightControl.count} 处关联高亮{highlightControl.skipped>0?` · ${highlightControl.skipped} 条依据版本或位置已变化，未高亮`: ''}<span className="chapter-highlight-key" aria-label="关联类型颜色；重叠处用多条色线表示">{Object.entries(linkedTypeLabels).map(([type,label])=><span key={type} style={{'--linked-tone':`var(--linked-${type})`}}>{label}</span>)}</span></p>}{people.length>0&&<section><h3>关联人物与世界书</h3><div className="chapter-reference-cards">{people.map(n=><button className="chapter-reference" key={n.id} onClick={()=>onMemory(n.id)}><span className="reference-avatar">{n.avatarImage?<img src={n.avatarImage} alt=""/>:n.name.slice(0,1)}</span><strong>{n.name}</strong></button>)}</div></section>}{cards.length>0&&<section><h3>本章剧情卡</h3><div className="chapter-reference-cards">{cards.map(c=><button className="chapter-reference" key={c.id} onClick={()=>onStoryCard?.(c.id)}><Icon name="route"/><span><strong>{c.title}</strong><small>{storyTimeLabel(c,data.state.storyAxis)} · {(c.evidence||[]).some(e=>e.chapterId===chapterId)?'有正文依据':'计划'}</small></span></button>)}</div></section>}{shadows.length>0&&<section><h3>本章伏笔</h3><div className="chapter-reference-cards">{shadows.map(f=><button className="chapter-reference" key={f.id} onClick={()=>onForeshadow(f.id)}><Icon name="bookmark"/><span><strong>{f.title}</strong><small>{f.review?'依据待复核':{planned:'计划',planted:'埋设',developing:'推进',partial:'部分回收',recovered:'已回收',abandoned:'已放弃'}[f.status]}</small></span></button>)}</div></section>}</aside>;
}
